<?php
$root = dirname(__DIR__);
require_once $root . '/app/Core/Installer.php';
function install_escape($value){return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');}
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
$installer = new Installer($root);
if (!empty($_SESSION['install_csrf']) === false) $_SESSION['install_csrf'] = bin2hex(random_bytes(32));
$csrf = $_SESSION['install_csrf'];
$errors = array(); $success = false;
if ($installer->isInstalled()) $success = true;
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !$success) {
    if (!isset($_POST['_csrf']) || !hash_equals($csrf, (string)$_POST['_csrf'])) $errors[] = '请求已过期，请刷新页面重试。';
    else {
        try { $_SESSION['install_result'] = $installer->install($_POST); $success = true; session_regenerate_id(true); unset($_SESSION['install_csrf']); }
        catch (Exception $e) { $errors[] = $e->getMessage(); }
    }
}
$installResult = $success && isset($_SESSION['install_result']) ? $_SESSION['install_result'] : null;
if ($success && $installResult) unset($_SESSION['install_result']);
$old = $_POST;
$checks = $installer->environment();
$allReady = true; foreach ($checks as $check) if (!$check[1] && strpos($check[0], '在线更新') === false) $allReady = false;
function install_field($name, $label, $old, $type='text', $required=true){return '<label>'.install_escape($label).'<input type="'.install_escape($type).'" name="'.install_escape($name).'" value="'.($type==='password'?'':install_escape(isset($old[$name])?$old[$name]:'' )).'"'.($required?' required':'').'></label>';}
?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>初始化安装 - 小云铺加速器</title><link rel="icon" type="image/png" href="/assets/site-icon.png"><link rel="stylesheet" href="/assets/style.css"><style>body{background:#f4f7fb}.install-shell{max-width:860px;margin:40px auto;padding:0 18px}.install-card{background:#fff;border:1px solid #e7ebf2;border-radius:18px;padding:28px;box-shadow:0 12px 32px #2c477414}.install-head{text-align:center;margin-bottom:24px}.install-head img{height:48px;max-width:220px}.install-head h1{margin:15px 0 6px}.install-head p{color:#77849a}.install-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.install-section{border-top:1px solid #edf0f5;padding-top:18px;margin-top:20px}.install-section h2{font-size:17px}.install-section label{display:block;margin:12px 0;color:#526078;font-size:13px}.install-section input{display:block;width:100%;box-sizing:border-box;margin-top:7px;padding:11px 12px;border:1px solid #dce3ee;border-radius:8px}.install-checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.install-check{padding:9px 11px;border-radius:8px;background:#f7f9fc;font-size:12px}.install-check.ok{color:#21865b}.install-check.fail{color:#bd5964}.install-actions{text-align:center;margin-top:24px}.install-actions button{border:0;cursor:pointer}.install-error{padding:12px;border-radius:8px;background:#fff0f1;color:#b74e5a;margin-bottom:14px}.install-success{padding:24px;border-radius:12px;background:#eefaf4;color:#216e4f}.install-success a{color:#3c55b8}.install-note{font-size:12px;color:#7d899a;line-height:1.7}@media(max-width:650px){.install-grid,.install-checks{grid-template-columns:1fr}.install-card{padding:20px}}</style></head><body><main class="install-shell"><section class="install-card"><div class="install-head"><img src="/assets/xiaoyun-logo.png" alt="小云铺加速器"><h1>初始化安装</h1><p>首次部署请完成数据库、站点和管理员配置</p></div><?php if($success): ?><div class="install-success"><h2>系统已经完成初始化</h2><?php if($installResult): ?><p><strong>请立即保存以下自动生成的管理员信息，刷新后将不再显示密码：</strong></p><p>管理员账号：<input value="<?php echo install_escape($installResult['admin_email']); ?>" readonly></p><p>临时密码：<input type="password" value="<?php echo install_escape($installResult['admin_password']); ?>" readonly></p><p>管理员登录：<a href="/admin/login">进入管理后台</a></p><p>首次登录后请立即修改密码。</p><?php else: ?><p>为安全起见，初始化入口已锁定，不能重复安装。</p><p>管理员登录：<a href="/admin/login">进入管理后台</a></p><?php endif; ?><p class="install-note">请确认服务器已禁止外部访问 config、database、scripts 和 storage 目录。</p></div><?php else: ?><?php foreach($errors as $error): ?><div class="install-error"><?php echo install_escape($error); ?></div><?php endforeach; ?><div class="install-section"><h2>环境检查</h2><div class="install-checks"><?php foreach($checks as $check): ?><div class="install-check <?php echo $check[1]?'ok':'fail'; ?>"><?php echo $check[1]?'✓':'✕'; ?> <?php echo install_escape($check[0]); ?></div><?php endforeach; ?></div></div><form method="post" autocomplete="off"><input type="hidden" name="_csrf" value="<?php echo install_escape($csrf); ?>"><div class="install-section"><h2>站点配置</h2><div class="install-grid"><?php echo install_field('site_name','站点名称',$old); echo install_field('base_url','站点地址',$old); echo install_field('timezone','时区',$old); ?></div></div><div class="install-section"><h2>数据库配置</h2><div class="install-grid"><?php echo install_field('db_host','数据库主机',$old); echo install_field('db_port','数据库端口',$old); echo install_field('db_name','数据库名',$old); echo install_field('db_user','数据库用户名',$old); echo install_field('db_password','数据库密码',$old,'password'); ?></div></div><div class="install-section"><h2>管理员账号</h2><div class="install-grid"><?php echo install_field('admin_email','管理员邮箱',$old,'email'); echo install_field('admin_name','管理员名称',$old); echo install_field('admin_password','管理员密码（至少 12 位）',$old,'password'); echo install_field('admin_password_confirm','确认管理员密码',$old,'password'); ?></div></div><p class="install-note">安装会创建数据库表、生成随机加密密钥和管理员账号。不会把密码写入日志或安装锁。请先确认数据库已创建且账号拥有建表权限。</p><div class="install-actions"><button class="button" type="submit" <?php echo $allReady?'':'disabled'; ?>>开始初始化安装</button></div></form><?php endif; ?></section></main></body></html>
